import{_ as t,o as d,c as e,Q as a}from"./chunks/framework.48927342.js";const f=JSON.parse('{"title":"Telling the Time","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/06-time-calendar.md","filePath":"en/more/maltese/grammar/06-time-calendar.md"}'),i={name:"en/more/maltese/grammar/06-time-calendar.md"},r=a('<h1 id="telling-the-time" tabindex="-1">Telling the Time <a class="header-anchor" href="#telling-the-time" aria-label="Permalink to &quot;Telling the Time&quot;">​</a></h1><p>Maltese uses both traditional spoken clock expressions and numeric 24-hour time. Numeric notation is clearest when arranging a meeting. In spoken expressions, note the forms of <code>siegħa</code> (hour) and the clock numerals.</p><h2 id="_1-asking-the-time-and-saying-o-clock" tabindex="-1">1. Asking the Time and Saying O&#39;Clock <a class="header-anchor" href="#_1-asking-the-time-and-saying-o-clock" aria-label="Permalink to &quot;1. Asking the Time and Saying O&#39;Clock&quot;">​</a></h2><ul><li><code>X&#39;ħin hu?</code>: What time is it?</li><li><code>Huwa s-sagħtejn.</code>: It is two o&#39;clock.</li><li><code>Hija s-siegħa.</code>: It is one o&#39;clock.</li><li><code>Huma t-tlieta.</code>: It is three o&#39;clock.</li></ul><p>Common o&#39;clock forms are below. Noon and midnight are also commonly expressed as <code>nofsinhar</code> and <code>nofsillejl</code>; articles and colloquial forms may vary slightly by context.</p><table><thead><tr><th>Time</th><th>English</th><th>Common Malti</th></tr></thead><tbody><tr><td>01:00</td><td>one o&#39;clock</td><td>is-siegħa</td></tr><tr><td>02:00</td><td>two o&#39;clock</td><td>is-sagħtejn</td></tr><tr><td>03:00</td><td>three o&#39;clock</td><td>it-tlieta</td></tr><tr><td>04:00</td><td>four o&#39;clock</td><td>l-erbgħa</td></tr><tr><td>05:00</td><td>five o&#39;clock</td><td>il-ħamsa</td></tr><tr><td>06:00</td><td>six o&#39;clock</td><td>is-sitta</td></tr><tr><td>07:00</td><td>seven o&#39;clock</td><td>is-sebgħa</td></tr><tr><td>08:00</td><td>eight o&#39;clock</td><td>it-tmienja</td></tr><tr><td>09:00</td><td>nine o&#39;clock</td><td>id-disgħa</td></tr><tr><td>10:00</td><td>ten o&#39;clock</td><td>l-għaxra</td></tr><tr><td>11:00</td><td>eleven o&#39;clock</td><td>il-ħdax</td></tr><tr><td>12:00</td><td>noon / midnight</td><td>nofsinhar / nofsillejl</td></tr></tbody></table><p>Ask <code>X&#39;ħin hu?</code>. In response, give the clock expression or numeric time, for example <code>Huwa s-sagħtejn.</code> (It is two o&#39;clock) or <code>Huwa 14:00.</code> (It is 14:00).</p><h2 id="_2-parts-of-the-day-and-relative-time" tabindex="-1">2. Parts of the Day and Relative Time <a class="header-anchor" href="#_2-parts-of-the-day-and-relative-time" aria-label="Permalink to &quot;2. Parts of the Day and Relative Time&quot;">​</a></h2><table><thead><tr><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>morning</td><td>filgħodu</td></tr><tr><td>morning; before noon</td><td>filgħodu</td></tr><tr><td>midday</td><td>nofsinhar</td></tr><tr><td>afternoon</td><td>wara nofsinhar</td></tr><tr><td>evening</td><td>filgħaxija</td></tr><tr><td>night</td><td>billejl</td></tr><tr><td>today</td><td>illum</td></tr><tr><td>tomorrow</td><td>għada</td></tr><tr><td>yesterday</td><td>ilbieraħ</td></tr><tr><td>day after tomorrow</td><td>pitgħada</td></tr><tr><td>now</td><td>issa</td></tr><tr><td>last week</td><td>il-ġimgħa li għaddiet</td></tr><tr><td>this week</td><td>din il-ġimgħa</td></tr><tr><td>next week</td><td>il-ġimgħa d-dieħla</td></tr><tr><td>last month</td><td>ix-xahar li għadda</td></tr><tr><td>this month</td><td>dan ix-xahar</td></tr><tr><td>next month</td><td>ix-xahar id-dieħel</td></tr><tr><td>last year</td><td>is-sena l-oħra</td></tr><tr><td>this year</td><td>din is-sena</td></tr><tr><td>next year</td><td>is-sena d-dieħla</td></tr></tbody></table><p>A time of day can follow a specific time: <code>fit-07:15 ta&#39; filgħodu</code> (7:15 a.m.), <code>fl-14:30 ta&#39; wara nofsinhar</code> (2:30 p.m.), <code>fit-20:45 ta&#39; filgħaxija</code> (8:45 p.m.).</p><h2 id="_3-hours-and-minutes" tabindex="-1">3. Hours and Minutes <a class="header-anchor" href="#_3-hours-and-minutes" aria-label="Permalink to &quot;3. Hours and Minutes&quot;">​</a></h2><p><code>u</code> means “and/past” and is used for minutes after the hour: <code>it-tlieta u għaxar minuti</code> (ten past three). <code>nofs</code> means “half”: <code>it-tlieta u nofs</code> (half past three). <code>neqsin</code> is the plural of <code>nieqes</code> (missing/short) and expresses minutes to the next hour: <code>it-tlieta neqsin kwart</code> (a quarter to three, 2:45). Numeric time is clearest for minutes that are not a quarter-hour. Before a time, <code>f&#39;</code> is commonly used and contracts with the article according to spelling conventions.</p><ul><li><code>it-tlieta u kwart</code>: quarter past three (3:15)</li><li><code>it-tlieta u nofs</code>: half past three (3:30)</li><li><code>it-tlieta neqsin kwart</code>: quarter to three (2:45)</li><li><code>l-erbgħa neqsin għaxar minuti</code>: ten to four (3:50)</li><li><code>fit-08:15</code>: at 08:15</li><li><code>fit-14:30</code>: at 14:30</li><li><code>fit-18:45</code>: at 18:45</li></ul><p>For hours and minutes, say the hour first and then the minutes. If unsure about the traditional spoken form, use 24-hour numeric notation. Numeric notation is also recommended for formal appointments, tickets, and itineraries.</p><h2 id="_4-twenty-clock-time-expressions" tabindex="-1">4. Twenty Clock-Time Expressions <a class="header-anchor" href="#_4-twenty-clock-time-expressions" aria-label="Permalink to &quot;4. Twenty Clock-Time Expressions&quot;">​</a></h2><p>These are time expressions, not full sentences. <code>ta&#39; filgħodu</code>, <code>ta&#39; wara nofsinhar</code>, and <code>ta&#39; filgħaxija</code> indicate morning, afternoon, and evening. Use the 24-hour clock when you need to avoid ambiguity.</p><table><thead><tr><th style="text-align:right;">#</th><th>English time</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>1:00 a.m.</td><td>is-siegħa ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">2</td><td>7:00 a.m.</td><td>is-sebgħa ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">3</td><td>8:15 a.m.</td><td>it-tmienja u kwart ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">4</td><td>8:30 a.m.</td><td>it-tmienja u nofs ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">5</td><td>8:45 a.m.</td><td>id-disgħa neqsin kwart ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">6</td><td>9:10 a.m.</td><td>id-disgħa u għaxar minuti ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">7</td><td>9:55 a.m.</td><td>l-għaxra neqsin ħames minuti ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">8</td><td>11:20 a.m.</td><td>il-ħdax u għoxrin minuta ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">9</td><td>12:00 noon</td><td>nofsinhar</td></tr><tr><td style="text-align:right;">10</td><td>1:15 p.m.</td><td>is-siegħa u kwart ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">11</td><td>2:30 p.m.</td><td>is-sagħtejn u nofs ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">12</td><td>2:45 p.m.</td><td>it-tlieta neqsin kwart ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">13</td><td>3:10 p.m.</td><td>it-tlieta u għaxar minuti ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">14</td><td>3:50 p.m.</td><td>l-erbgħa neqsin għaxar minuti ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">15</td><td>5:20 p.m.</td><td>il-ħamsa u għoxrin minuta ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">16</td><td>6:00 p.m.</td><td>is-sitta ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">17</td><td>7:15 p.m.</td><td>is-sebgħa u kwart ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">18</td><td>8:30 p.m.</td><td>it-tmienja u nofs ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">19</td><td>8:55 p.m.</td><td>id-disgħa neqsin ħames minuti ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">20</td><td>12:00 midnight</td><td>nofsillejl</td></tr></tbody></table><h2 id="_5-durations" tabindex="-1">5. Durations <a class="header-anchor" href="#_5-durations" aria-label="Permalink to &quot;5. Durations&quot;">​</a></h2><p>Use <code>għal + duration</code> to express “for a duration”; <code>idum</code> (to last/take) can also state how long something takes. Minutes are <code>minuta/minuti</code>; <code>kwarta</code> means a quarter of an hour, and <code>nofs siegħa</code> means half an hour. <code>sagħtejn</code> is a common dual form for two hours; <code>sigħat</code> is used for multiple hours. Two days can be expressed as <code>jumejn</code>.</p><table><thead><tr><th style="text-align:right;">#</th><th>English duration</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>one minute</td><td>minuta</td></tr><tr><td style="text-align:right;">2</td><td>two minutes</td><td>żewġ minuti</td></tr><tr><td style="text-align:right;">3</td><td>five minutes</td><td>ħames minuti</td></tr><tr><td style="text-align:right;">4</td><td>ten minutes</td><td>għaxar minuti</td></tr><tr><td style="text-align:right;">5</td><td>a quarter of an hour</td><td>kwart ta&#39; siegħa</td></tr><tr><td style="text-align:right;">6</td><td>a quarter of an hour</td><td>kwarta</td></tr><tr><td style="text-align:right;">7</td><td>half an hour</td><td>nofs siegħa</td></tr><tr><td style="text-align:right;">8</td><td>one hour</td><td>siegħa</td></tr><tr><td style="text-align:right;">9</td><td>two hours</td><td>sagħtejn</td></tr><tr><td style="text-align:right;">10</td><td>three hours</td><td>tliet sigħat</td></tr><tr><td style="text-align:right;">11</td><td>four hours</td><td>erba&#39; sigħat</td></tr><tr><td style="text-align:right;">12</td><td>a few hours</td><td>ftit sigħat</td></tr><tr><td style="text-align:right;">13</td><td>one day</td><td>jum wieħed</td></tr><tr><td style="text-align:right;">14</td><td>two days</td><td>jumejn</td></tr><tr><td style="text-align:right;">15</td><td>three days</td><td>tlett ijiem</td></tr><tr><td style="text-align:right;">16</td><td>one week</td><td>ġimgħa</td></tr><tr><td style="text-align:right;">17</td><td>two weeks</td><td>żewġ ġimgħat</td></tr><tr><td style="text-align:right;">18</td><td>three weeks</td><td>tliet ġimgħat</td></tr><tr><td style="text-align:right;">19</td><td>one month</td><td>xahar</td></tr><tr><td style="text-align:right;">20</td><td>one year</td><td>sena</td></tr></tbody></table>',20),o=[r];function n(s,l,h,g,c,m){return d(),e("div",null,o)}const x=t(i,[["render",n]]);export{f as __pageData,x as default};
